1	#!/usr/bin/env bun
2	/**
3	 * claim_turn.ts — claim the turn: which run took up which ask (#285).
4	 *
5	 * The runner writes one comment at start —
6	 *
7	 *     <!-- atomaton:llm-context=exclude -->
8	 *     <!-- atomaton:took=<ask comment id> run=<run id> -->
9	 *     Atomaton: claimed this turn.
10	 *
11	 * — and that comment is the turn's identity from the taking side. The run watch
12	 * compares it against the endings by run id ("did THIS run take a turn", "did THIS
13	 * run report"), and the guard's shaping reads it as the ball being with an agent.
14	 * What the claim replaces is estimation: a marker or a command inside a run's
15	 * lifetime used to be attributed by timestamp, and two runs close together were
16	 * attributed to the wrong one — #281's both halves.
17	 *
18	 * ## The race, and why it cannot happen here
19	 *
20	 * Two runs reaching for one ask is a dispatch-level failure (the ordering check or
21	 * the ask check should have stopped the second dispatch), so this is defence in
22	 * depth — but it is depth that cannot itself race, because the runner runs under
23	 * `atomaton-<type>-<number>` concurrency with `cancel-in-progress: false`: two runs
24	 * on one node are serialised, so the second claims only after the first has
25	 * finished. The check still runs, because queues are exactly when identity
26	 * mistakes are made: post the claim, wait until the listing shows it (GitHub does
27	 * not guarantee read-after-write — the same instrument `postDispatchMarker` runs),
28	 * then read the thread again and look for ANOTHER claim on the same ask with a
29	 * smaller comment id. Found one, this run backs off: it deletes its own claim and
30	 * writes `claimed=false`, and the workflow steps that would take the turn are
31	 * gated off it. The other run — its claim is older — holds the turn, and a backed
32	 * off run leaves no ending, because it took no turn the thread names.
33	 *
34	 * ## The exit code
35	 *
36	 * A claim GitHub refused is a machinery failure and exits non-zero: the run would
37	 * otherwise work without its identity on the thread, which is the state every
38	 * later comparison misreads. A backed-off claim is `0` — the back-off is the
39	 * correct outcome, not a fault — and the job goes green having done nothing,
40	 * which is what losing a race looks like.
41	 *
42	 * Usage:
43	 *   claim_turn.ts --number N --ask ID --run-id ID [--repo R]
44	 * Writes `claimed=true|false` to $GITHUB_OUTPUT.
45	 */
46	import { parseArgs } from "node:util";
47	import { gh, ghRead, splitConcatenatedJson } from "../../adapters/github/gh.ts";
48	import { LLM_CONTEXT_TAG, TOOK_TAG } from "../../adapters/github/tags.ts";
49	import { defineScript } from "./lib/script-ref.ts";
50	
51	export interface ClaimTurnArgs {
52	  number: string | number;
53	  /** The ask comment id this run takes up; empty for a run whose ask is the body. */
54	  ask?: string;
55	  "run-id"?: string;
56	  repo?: string;
57	}
58	
59	export const ref = defineScript<ClaimTurnArgs>(import.meta.url);
60	
61	/** Delays between reads while waiting for the listing to show the claim. */
62	const READ_DELAYS_MS = [1_000, 2_000, 4_000];
63	
64	/** Every comment on the node, oldest first, as the race check reads them. */
65	function listBodies(repo: string, number: number): { id: number; body: string }[] {
66	  const listed = ghRead("api", `repos/${repo}/issues/${number}/comments`, "--paginate", "--jq", ".");
67	  if (listed.code !== 0) throw new Error(`could not read #${number}'s comments: ${listed.stderr || listed.stdout}`);
68	  const comments: { id: number; body: string }[] = [];
69	  for (const page of splitConcatenatedJson(listed.stdout || "[]")) {
70	    if (!Array.isArray(page)) continue;
71	    for (const entry of page as { id?: number; body?: string }[]) {
72	      if (typeof entry.id === "number") comments.push({ id: entry.id, body: entry.body ?? "" });
73	    }
74	  }
75	  return comments;
76	}
