94	/**
95	 * Whether this run holds the turn for its ask: the claim is posted, visible, and
96	 * no older claim on the same ask exists.
97	 *
98	 * Split out of `main` so the read-after-write and the id comparison are testable
99	 * without GitHub: the caller hands in the comments as they stand and the id the
100	 * run's own claim carries.
101	 */
102	export function raceOutcome(
103	  comments: readonly { id: number; body: string }[],
104	  mine: { id: number; ask: number },
105	): "held" | "backed-off" {
106	  for (const comment of comments) {
107	    if (comment.id >= mine.id) break; // oldest first; nothing newer can have claimed first
108	    // Prose only: a comment quoting a took tag in a fenced sample has not claimed
109	    // anything (#304).
110	    const claim = TOOK_TAG.readProse(comment.body);
111	    if (claim !== undefined && claim.ask === mine.ask) return "backed-off";
112	  }
113	  return "held";
114	}
